<?php declare(strict_types=1);
/** Claim correction controls and bounded immutable history share the original receipt scope. */
if($reimbursementCancelAllowed&&!isset($reimbursementFormState['review'])):
$cancelDraft=$reimbursementOperation==='cancel';$cancelKey=$cancelDraft?$reimbursementKey:bin2hex(random_bytes(16));?>
<details data-reimbursement-cancel <?=$cancelDraft?'open':''?>><summary><?=e($reimbursementText('Irrtümlich erfassten Erstattungsfall verwerfen'))?></summary>
<p><?=e($reimbursementText('Nur die irrtümliche Erfassung wird verworfen. Rechnung und Geldbewegungen bleiben bestehen. Dies ist kein Aufwandsverzicht.'))?></p>
<form method="post" action="<?=e($reimbursementAction('cancel',$cancelKey))?>" class="form-stack"><?=csrf().hidden('action','reimbursement-cancel').hidden('id',$r['id']).hidden('request_key',$cancelKey).hidden('entry_version',$cancelDraft?$reimbursementScalar('entry_version'):$r['version']).hidden('claim_id',$cancelDraft?$reimbursementScalar('claim_id'):$reimbursement['id']).hidden('claim_version',$cancelDraft?$reimbursementScalar('claim_version'):$reimbursement['version'])?>
<label><?=e($reimbursementText('Begründung'))?><textarea class="form-control" name="reason" maxlength="500" required><?=e($cancelDraft?$reimbursementScalar('reason'):'')?></textarea></label>
<label class="reimbursement-check"><input type="checkbox" name="reimbursement_mistake" value="1" required <?=$cancelDraft&&$reimbursementScalar('reimbursement_mistake')==='1'?'checked':''?>><span><?=e($reimbursementText('Dieser Erstattungsfall wurde irrtümlich erfasst. Ich gebe keinen bestehenden Anspruch auf.'))?></span></label>
<button class="btn btn-outline"><?=e($reimbursementText('Verwerfen prüfen'))?></button><?=hidden(\Kulturhus\Verein\Web\ReimbursementForm::COMPLETE,'1')?><?php $reimbursementRecheck();$reimbursementReadLink($cancelKey);?></form></details>
<?php endif;
if($reimbursement&&$reimbursement['state']==='approved'):?><p><?=e($reimbursementText('Für eine Berichtigung zuerst die Rechnungsfreigabe zurücknehmen. Bereits zugeordnete oder laufende Zahlungen müssen vorher gesondert geklärt werden.'))?></p><?php endif;
try{$claimHistory=\Kulturhus\Verein\ReimbursementActionOriginals::history($db,(string)$_SESSION['actor'],$r['id'],$_GET['reimbursement_history_page']??'1');?>
<details data-reimbursement-history <?=array_key_exists('reimbursement_history_page',$_GET)?'open':''?>><summary><?=e($reimbursementText('Erstattungsverlauf · {count} gespeicherte Vorgänge',['count'=>$claimHistory['count']]))?></summary>
<p><?=e($reimbursementText('Der Verlauf enthält die gespeicherten Auftragsnachweise. Für ältere Erfassungen ohne solchen Nachweis wird kein ursprünglicher Ausgang nachgebildet.'))?></p>
<?php if(!$claimHistory['rows']):?><p><?=e($reimbursementText('Noch kein gespeicherter Auftragsnachweis vorhanden.'))?></p><?php else:?><ol class="reimbursement-history-list">
<?php foreach($claimHistory['rows']as$historyRow):?><li><strong><?=e($reimbursementText($reimbursementLabels[$historyRow['operation']]))?></strong><p><?=e($historyRow['created_at'])?> · <?=e($reimbursementText('Anspruchsfassung {version}',['version'=>$historyRow['claim_version']]))?></p><?php if($historyRow['reason']!==''):?><p><?=e($historyRow['reason'])?></p><?php endif?><a href="<?=e(url($reimbursementBase+['reimbursement_saved'=>$historyRow['request_key']]).'#reimbursement')?>"><?=e($reimbursementText('Gespeicherten Ausgang lesen'))?></a></li><?php endforeach?></ol><?php endif?>
<p><?=e($reimbursementText('Seite {page} von {pages}',$claimHistory))?></p><nav class="reimbursement-pages" aria-label="<?=e($reimbursementText('Verlaufsseiten'))?>"><?php foreach([-1=>'Vorherige',1=>'Nächste']as$offset=>$label):$historyPage=$claimHistory['page']+$offset;if($historyPage>=1&&$historyPage<=$claimHistory['pages']):?><a class="btn btn-outline" href="<?=e(url($reimbursementBase+['reimbursement_history_page'=>$historyPage]).'#reimbursement')?>"><?=e($reimbursementText($label))?></a><?php endif;endforeach?></nav></details>
<?php }catch(DomainException$failure){?><p class="notice" role="alert" data-reimbursement-history-error><?=e($reimbursementText($failure->getMessage()))?></p><?php }catch(Throwable){?><p class="notice" role="alert" data-reimbursement-history-error><?=e($reimbursementText('Erstattungsverlauf momentan nicht lesbar. Gespeicherte Vorgänge später erneut lesen.'))?></p><?php } ?>
